select jsonb_build_object('at',now(),'migrations',(select count(*) from supabase_migrations.schema_migrations),'expiry',(select jsonb_build_object('room',to_jsonb(r),'boss',to_jsonb(b)) from public.raid_rooms r join public.raid_bosses b on b.id=r.raid_boss_instance_id where r.id='3972a461-b45f-4b02-8142-75f294461ae3'),'cron',(select jsonb_agg(to_jsonb(t) order by jobid) from (select jobid,jobname,schedule,command,active from cron.job)t),'originalUsers',(select jsonb_build_object('count',count(*),'md5',md5(jsonb_agg(to_jsonb(t) order by id)::text)) from public.users t where created_at<'2026-09-08T10:22:54.545Z')) state;
